}
data class Pair231<A, B>(val first: A, val second: B)

fun combine231(left: Int, right: Int): Pair231<Int, Int> {
    return Pair231(left + 20, right + 59)
}
fun <T, R> List<T>.mapChecked232(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
